import { useDataCellSelectActivation } from "@/registry/new-york-v4/ui/data-cell-select-activation";
import { useDataCellSelectKeyboard } from "@/registry/new-york-v4/ui/data-cell-select-keyboard";
import { DataCellSelectPopup } from "@/registry/new-york-v4/ui/data-cell-select-popup";
import { useDataCellSelectState } from "@/registry/new-york-v4/ui/data-cell-select-state";

export function DataCellSelectControl({
  kind,
  value,
  disabled = false,
  name,
  placeholder = "Select...",
  className,
  formatValue,
  autoFocus,
  activationSource,
  session,
  openState,
  options,
  onFocus,
  onBlur,
  onKeyDown,
  onClick,
  onDoubleClick,
  ...props
}: DataCellSelectControlProps) {
  const triggerRef = React.useRef<HTMLButtonElement>(null);
  const popupId = React.useId();
  const select = useDataCellSelectState({
    popupId,
    value,
    placeholder,
    formatValue,
    openState,
    selectOptions: options,
    session,
  });
  const openEditor = React.useCallback(() => {
    select.openEditor(triggerRef.current);
  }, [select.openEditor]);
  const activation = useDataCellSelectActivation({
    activationSource,
    autoFocus,
    triggerRef,
    openEditor,
    closeEditor: select.closeEditor,
    keepOpen: select.keepOpen,
  });
  const {
    shouldCancelDismiss,
    closeEditor: closeActivatedEditor,
    openEditor: openActivatedEditor,
    release,
  } = activation;
  const commitValue = React.useCallback(
    (nextValue: string) => {
      release();
      select.commitValue(nextValue);
    },
    [release, select.commitValue],
  );
  const selectOnKeyDown = useDataCellSelectKeyboard({
    activeOption: select.activeOption,
    open: select.open,
    options,
    openEditor: openActivatedEditor,
    closeEditor: closeActivatedEditor,
    commitValue,
    setActiveOptionIndex: select.setActiveOptionIndex,
    shouldCancelDismiss,
  });

  return (
    <>
      <button
        {...props}
        ref={triggerRef}
        type="button"
        name={name}
        role="combobox"
        aria-expanded={select.open}
        aria-controls={select.open ? popupId : undefined}
        aria-haspopup="listbox"
        aria-activedescendant={select.activeDescendantId}
        disabled={disabled}
        data-slot="data-cell"
        data-kind={kind}
        data-mode="edit"
        className={cn(dataCellPickerTriggerClass, className)}
        onFocus={onFocus}
        onBlur={(event) => {
          onBlur?.(event);
          const nextFocusTarget = event.relatedTarget;
          const isPopupFocus =
            nextFocusTarget instanceof Node &&
            document.getElementById(popupId)?.contains(nextFocusTarget);
          if (!isPopupFocus && !shouldCancelDismiss("focus-out", undefined)) {
            closeActivatedEditor();
          }
        }}
        onClick={(event) => {
          onClick?.(event);
          if (event.defaultPrevented) return;
          if (!select.open) {
            openActivatedEditor();
            return;
          }
          if (!shouldCancelDismiss("trigger-press", event.nativeEvent)) {
            closeActivatedEditor();
          }
        }}
        onDoubleClick={onDoubleClick}
        onKeyDown={(event) => {
          onKeyDown?.(event);
          if (event.defaultPrevented) return;
          selectOnKeyDown(event);
        }}
      >
        <span
          data-slot="select-value"
          className={cn(
            "flex-1 truncate",
            select.isEmpty && "text-muted-foreground",
          )}
        >
          {select.isEmpty ? select.placeholder : select.displayValue}
        </span>
        <ChevronDown className="-me-1 size-4.5 opacity-80 sm:size-4" />
      </button>
      {select.open && triggerRef.current && select.popupPosition ? (
        <DataCellSelectPopup
          anchor={triggerRef.current}
          id={popupId}
          position={select.popupPosition}
          activeDescendantId={select.activeDescendantId}
          value={select.selectedValue}
          activeIndex={select.activeOptionIndex}
          options={options}
          onActiveIndexChange={select.setActiveOptionIndex}
          onCommit={commitValue}
          onCancel={closeActivatedEditor}
          onOutsidePointerDown={(event) => {
            if (shouldCancelDismiss("outside-pointer", event)) {
              return;
            }
            closeActivatedEditor();
          }}
        />
      ) : null}
    </>
  );
}

"use client";

import * as React from "react";

import {
  firstEnabledDataCellSelectOptionIndex,
  lastEnabledDataCellSelectOptionIndex,
  nextEnabledDataCellSelectOptionIndex,
} from "@/registry/new-york-v4/ui/data-cell-select-navigation";
import type { DataCellSelectOption } from "@/registry/new-york-v4/ui/data-cell-types";

export function useDataCellSelectKeyboard({
  activeOption,
  open,
  options,
  openEditor,
  closeEditor,
  commitValue,
  setActiveOptionIndex,
  shouldCancelDismiss,
}: {
  activeOption: DataCellSelectOption | undefined;
  open: boolean;
  options: DataCellSelectOption[];
  openEditor: () => void;
  closeEditor: () => void;
  commitValue: (value: string) => void;
  setActiveOptionIndex: React.Dispatch<React.SetStateAction<number>>;
  shouldCancelDismiss: (kind: "escape", event: Event | undefined) => boolean;
}) {
  return React.useCallback(
    (event: React.KeyboardEvent<HTMLButtonElement>) => {
      if (event.key === "Escape") {
        event.preventDefault();
        if (!shouldCancelDismiss("escape", event.nativeEvent)) closeEditor();
        return;
      }

      if (event.key === "ArrowDown" || event.key === "ArrowUp") {
        event.preventDefault();
        if (!open) {
          openEditor();
          return;
        }
        setActiveOptionIndex((currentIndex) =>
          nextEnabledDataCellSelectOptionIndex({
            options,
            currentIndex,
            direction: event.key === "ArrowDown" ? 1 : -1,
          }),
        );
        return;
      }

      if (event.key === "Home" || event.key === "End") {
        event.preventDefault();
        if (!open) {
          openEditor();
          return;
        }
        setActiveOptionIndex(
          event.key === "Home"
            ? firstEnabledDataCellSelectOptionIndex(options)
            : lastEnabledDataCellSelectOptionIndex(options),
        );
        return;
      }

      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        if (!open) {
          openEditor();
          return;
        }
        if (activeOption && !activeOption.disabled) {
          commitValue(activeOption.value);
        }
      }
    },
    [
      activeOption,
      closeEditor,
      commitValue,
      open,
      openEditor,
      options,
      setActiveOptionIndex,
      shouldCancelDismiss,
    ],
  );
}

import type { DataCellSelectOption } from "@/registry/new-york-v4/ui/data-cell-types";

export function firstEnabledDataCellSelectOptionIndex(
  options: DataCellSelectOption[],
) {
  return options.findIndex((option) => !option.disabled);
}

export function lastEnabledDataCellSelectOptionIndex(
  options: DataCellSelectOption[],
) {
  for (let index = options.length - 1; index >= 0; index -= 1) {
    if (!options[index]?.disabled) return index;
  }

  return -1;
}

export function nextEnabledDataCellSelectOptionIndex({
  options,
  currentIndex,
  direction,
}: {
  options: DataCellSelectOption[];
  currentIndex: number;
  direction: 1 | -1;
}) {
  if (options.length === 0) return -1;

  for (let offset = 1; offset <= options.length; offset += 1) {
    const index =
      (currentIndex + direction * offset + options.length) % options.length;
    if (!options[index]?.disabled) return index;
  }

  return -1;
}

export function selectedDataCellSelectOptionIndex({
  options,
  value,
}: {
  options: DataCellSelectOption[];
  value: string | null;
}) {
  const selectedIndex = options.findIndex((option) => option.value === value);
  if (selectedIndex >= 0 && !options[selectedIndex]?.disabled) {
    return selectedIndex;
  }

  return firstEnabledDataCellSelectOptionIndex(options);
}

"use client";

import type * as React from "react";
import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";
import { joinEffectKey } from "@/lib/effect-key";

export function useDataCellSelectPopupDismissal({
  anchor,
  popupRef,
  onCancel,
  onOutsidePointerDown,
}: {
  anchor: HTMLElement;
  popupRef: React.RefObject<HTMLElement | null>;
  onCancel: () => void;
  onOutsidePointerDown: (event: PointerEvent) => void;
}) {
  useKeyedMountEffect(
    joinEffectKey([anchor, onOutsidePointerDown, popupRef]),
    () => {
      const handlePointerDown = (event: PointerEvent) => {
        const target = event.target;
        if (!(target instanceof Node)) return;
        if (anchor.contains(target) || popupRef.current?.contains(target))
          return;

        onOutsidePointerDown(event);
      };

      document.addEventListener("pointerdown", handlePointerDown, true);
      return () =>
        document.removeEventListener("pointerdown", handlePointerDown, true);
    },
  );

  useKeyedMountEffect(joinEffectKey([onCancel, popupRef]), () => {
    const handleViewportChange = (event: Event) => {
      const target = event.target;
      if (target instanceof Node && popupRef.current?.contains(target)) return;
      onCancel();
    };

    window.addEventListener("resize", handleViewportChange);
    window.addEventListener("scroll", handleViewportChange, true);
    return () => {
      window.removeEventListener("resize", handleViewportChange);
      window.removeEventListener("scroll", handleViewportChange, true);
    };
  });
}

export type DataCellSelectPopupPosition = {
  left: number;
  top: number;
  width: number;
  maxHeight: number;
};

export type DataCellSelectPopupRect = Pick<
  DOMRect,
  "bottom" | "left" | "top" | "width"
>;

export type DataCellSelectPopupViewport = {
  width: number;
  height: number;
};

const popupGapPx = 4;
const viewportMarginPx = 8;
const minimumPopupHeightPx = 64;

export function getDataCellSelectPopupPosition({
  anchorRect,
  viewport,
}: {
  anchorRect: DataCellSelectPopupRect;
  viewport: DataCellSelectPopupViewport;
}): DataCellSelectPopupPosition {
  const availableBelow = viewport.height - anchorRect.bottom - viewportMarginPx;
  const availableAbove = anchorRect.top - viewportMarginPx;
  const shouldPlaceAbove =
    availableBelow < minimumPopupHeightPx && availableAbove > availableBelow;
  const maxHeight = Math.max(
    minimumPopupHeightPx,
    shouldPlaceAbove
      ? availableAbove - popupGapPx
      : availableBelow - popupGapPx,
  );
  const top = shouldPlaceAbove
    ? Math.max(viewportMarginPx, anchorRect.top - popupGapPx - maxHeight)
    : Math.min(
        anchorRect.bottom + popupGapPx,
        viewport.height - viewportMarginPx,
      );
  const left = Math.min(
    Math.max(viewportMarginPx, anchorRect.left),
    Math.max(
      viewportMarginPx,
      viewport.width - anchorRect.width - viewportMarginPx,
    ),
  );

  return {
    left,
    top,
    width: anchorRect.width,
    maxHeight,
  };
}

