import type { DataCellSelectOption } from "@/registry/new-york-v4/ui/data-cell-types";

export type DataCellSelectPopupProps = {
  anchor: HTMLElement;
  id: string;
  position: DataCellSelectPopupPosition;
  activeDescendantId: string | undefined;
  value: string | null;
  activeIndex: number;
  options: DataCellSelectOption[];
  onActiveIndexChange: (index: number) => void;
  onCommit: (value: string) => void;
  onCancel: () => void;
  onOutsidePointerDown: (event: PointerEvent) => void;
};

export function DataCellSelectPopup({
  anchor,
  id,
  position,
  activeDescendantId,
  value,
  activeIndex,
  options,
  onActiveIndexChange,
  onCommit,
  onCancel,
  onOutsidePointerDown,
}: DataCellSelectPopupProps) {
  const popupRef = React.useRef<HTMLDivElement>(null);

  useDataCellSelectPopupDismissal({
    anchor,
    popupRef,
    onCancel,
    onOutsidePointerDown,
  });

  return createPortal(
    <div
      ref={popupRef}
      id={id}
      role="listbox"
      aria-activedescendant={activeDescendantId}
      className="bg-popover text-foreground fixed z-[60] overflow-y-auto rounded-lg border p-1 shadow-lg/5 outline-none select-none"
      data-slot="data-cell-select-popup"
      style={{
        left: position.left,
        top: position.top,
        width: position.width,
        minWidth: position.width,
        maxHeight: position.maxHeight,
      }}
    >
      {options.map((option, index) => {
        const isSelected = option.value === value;
        const isActive = index === activeIndex;
        return (
          <div
            key={option.value}
            id={`${id}-option-${index}`}
            role="option"
            aria-selected={isSelected}
            aria-disabled={option.disabled || undefined}
            data-active={isActive ? "true" : undefined}
            data-disabled={option.disabled ? "true" : undefined}
            className={cn(
              "grid min-h-8 cursor-default grid-cols-[1rem_1fr] items-center gap-2 rounded-sm py-1 ps-2 pe-4 text-base outline-none sm:min-h-7 sm:text-sm",
              "data-[active=true]:bg-accent data-[active=true]:text-accent-foreground data-[disabled=true]:pointer-events-none data-[disabled=true]:opacity-64",
              option.className,
            )}
            onMouseEnter={() => {
              if (!option.disabled) onActiveIndexChange(index);
            }}
            onPointerDown={(event) => event.preventDefault()}
            onClick={() => {
              if (!option.disabled) onCommit(option.value);
            }}
          >
            <span className="col-start-1 flex size-4 items-center justify-center">
              {isSelected ? (
                <svg
                  aria-hidden="true"
                  className="size-4"
                  fill="none"
                  stroke="currentColor"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth="2"
                  viewBox="0 0 24 24"
                >
                  <path d="M5.252 12.7 10.2 18.63 18.748 5.37" />
                </svg>
              ) : null}
            </span>
            <span className="col-start-2 min-w-0 truncate">{option.label}</span>
          </div>
        );
      })}
    </div>,
    document.body,
  );
}

"use client";

import * as React from "react";

import { selectedDataCellSelectOptionIndex } from "@/registry/new-york-v4/ui/data-cell-select-navigation";
import {
  getDataCellSelectPopupPosition,
  type DataCellSelectPopupPosition,
} from "@/registry/new-york-v4/ui/data-cell-select-popup-position";
import type { DataCellPrimitiveSession } from "@/registry/new-york-v4/ui/data-cell-session";
import type { DataCellOpenControl } from "@/registry/new-york-v4/ui/data-cell-control-contract";
import type {
  DataCellSelectOption,
  DataCellValueMeta,
} from "@/registry/new-york-v4/ui/data-cell-types";

type DataCellSelectFormatValue = (
  value: string | null | undefined,
  meta: { kind: "select" },
) => React.ReactNode;

export type DataCellSelectState = {
  activeDescendantId: string | undefined;
  activeOption: DataCellSelectOption | undefined;
  activeOptionIndex: number;
  closeEditor: () => void;
  commitValue: (nextValue: string) => void;
  displayValue: React.ReactNode;
  isEmpty: boolean;
  keepOpen: () => void;
  open: boolean;
  openEditor: (trigger: HTMLElement | null) => void;
  placeholder: string;
  popupPosition: DataCellSelectPopupPosition | null;
  selectedValue: string | null;
  setActiveOptionIndex: React.Dispatch<React.SetStateAction<number>>;
};

export function useDataCellSelectState({
  popupId,
  value,
  placeholder = "Select...",
  formatValue,
  openState,
  selectOptions,
  session,
}: {
  popupId: string;
  value?: string | null;
  placeholder?: string;
  formatValue?: DataCellSelectFormatValue;
  openState?: DataCellOpenControl;
  selectOptions: DataCellSelectOption[];
  session: DataCellPrimitiveSession;
}): DataCellSelectState {
  const [uncontrolledOpen, setUncontrolledOpen] = React.useState(false);
  const [activeOptionIndex, setActiveOptionIndex] = React.useState(-1);
  const popupPositionRef = React.useRef<DataCellSelectPopupPosition | null>(
    null,
  );
  const [popupPosition, setPopupPosition] =
    React.useState<DataCellSelectPopupPosition | null>(null);
  const lastCommittedValueRef = React.useRef<string | null>(null);

  const controlledOpen = openState?.value;
  const open = controlledOpen ?? uncontrolledOpen;
  const selectedValue = value ?? null;
  const selectedOption = selectOptions.find((option) => option.value === value);
  const activeOption = selectOptions[activeOptionIndex];
  const activeDescendantId =
    open && activeOptionIndex >= 0
      ? `${popupId}-option-${activeOptionIndex}`
      : undefined;
  const displayValue =
    formatValue?.(selectedValue, { kind: "select" }) ??
    selectedOption?.label ??
    "";
  const isEmpty = displayValue === "";

  const setOpen = React.useCallback(
    (nextOpen: boolean) => {
      if (!nextOpen) {
        popupPositionRef.current = null;
        setPopupPosition(null);
      }
      if (controlledOpen === undefined) setUncontrolledOpen(nextOpen);
      openState?.onChange?.(nextOpen);
    },
    [controlledOpen, openState],
  );

  const keepOpen = React.useCallback(() => {
    if (controlledOpen === undefined) setUncontrolledOpen(true);
    openState?.onChange?.(true);
  }, [controlledOpen, openState]);

  const closeEditor = React.useCallback(() => {
    setOpen(false);
    session.end();
  }, [session, setOpen]);

  const openEditor = React.useCallback(
    (trigger: HTMLElement | null) => {
      if (!trigger) return;
      if (!popupPositionRef.current) {
        popupPositionRef.current = getDataCellSelectPopupPosition({
          anchorRect: trigger.getBoundingClientRect(),
          viewport: {
            width: window.innerWidth,
            height: window.innerHeight,
          },
        });
      }
      setPopupPosition(popupPositionRef.current);
      setActiveOptionIndex(
        selectedDataCellSelectOptionIndex({
          options: selectOptions,
          value: selectedValue,
        }),
      );
      lastCommittedValueRef.current = null;
      session.reset();
      setOpen(true);
    },
    [selectOptions, selectedValue, session, setOpen],
  );

  const commitValue = React.useCallback(
    (nextValue: string) => {
      if (selectedValue === nextValue) {
        closeEditor();
        return;
      }
      if (lastCommittedValueRef.current === nextValue) return;
      lastCommittedValueRef.current = nextValue;
      setOpen(false);
      session.commit(nextValue, selectValueMeta(nextValue));
    },
    [closeEditor, selectedValue, session, setOpen],
  );

  return {
    activeDescendantId,
    activeOption,
    activeOptionIndex,
    closeEditor,
    commitValue,
    displayValue,
    isEmpty,
    keepOpen,
    open,
    openEditor,
    placeholder,
    popupPosition,
    selectedValue,
    setActiveOptionIndex,
  };
}

function selectValueMeta(value: string | null): DataCellValueMeta {
  return {
    kind: "select",
    rawValue: value ?? "",
    isEmpty: value === null || value === "",
    isValid: true,
  };
}

"use client";

import * as React from "react";

import type {
  DataCellCommitValue,
  DataCellValueMeta,
} from "@/registry/new-york-v4/ui/data-cell-types";

type DataCellSessionCommitOptions = {
  endEditing?: boolean;
  markFinished?: boolean;
  shouldCommit?: () => boolean;
};

type DataCellSessionEndOptions = {
  markFinished?: boolean;
};

export type DataCellSessionCommit = (
  value: DataCellCommitValue,
  meta: DataCellValueMeta,
  options?: DataCellSessionCommitOptions,
) => void;

export type DataCellPrimitiveSession = {
  commit: DataCellSessionCommit;
  cancel: () => void;
  end: (options?: DataCellSessionEndOptions) => void;
  reset: () => void;
};

export function useDataCellPrimitiveSession({
  onCommit,
  onEditingEnd,
}: {
  onCommit?: (value: DataCellCommitValue, meta: DataCellValueMeta) => void;
  onEditingEnd?: () => void;
}): DataCellPrimitiveSession {
  const didFinishRef = React.useRef(false);

  const reset = React.useCallback(() => {
    didFinishRef.current = false;
  }, []);

  const end = React.useCallback(
    ({ markFinished = true }: DataCellSessionEndOptions = {}) => {
      if (didFinishRef.current) return;
      if (markFinished) didFinishRef.current = true;
      onEditingEnd?.();
    },
    [onEditingEnd],
  );

  const commit = React.useCallback<DataCellSessionCommit>(
    (
      value,
      meta,
      {
        endEditing = true,
        markFinished = true,
        shouldCommit,
      }: DataCellSessionCommitOptions = {},
    ) => {
      if (didFinishRef.current) return;
      if (shouldCommit && !shouldCommit()) return;
      if (markFinished) didFinishRef.current = true;
      onCommit?.(value, meta);
      if (endEditing) onEditingEnd?.();
    },
    [onCommit, onEditingEnd],
  );

  const cancel = React.useCallback(() => {
    end();
  }, [end]);

  return {
    commit,
    cancel,
    end,
    reset,
  };
}

"use client";

import * as React from "react";
import { useMountEffect } from "@/hooks/use-mount-effect";

import { cn } from "@/lib/utils";
import { Input } from "@/components/ui/input";
import {
  useDataCellOpeningContext,
  type DataCellActivationSource,
} from "@/registry/new-york-v4/ui/data-cell-activation";
import { dataCellDisplayClass } from "@/registry/new-york-v4/ui/data-cell-classes";
import type { DataCellInputControlProps } from "@/registry/new-york-v4/ui/data-cell-control-contract";
import {
  formatDataCellEditValue,
  getDataCellValueMeta,
  parseDataCellInputValue,
} from "@/registry/new-york-v4/ui/data-cell-format";
import { getDataCellTextSelectionOffset } from "@/registry/new-york-v4/ui/data-cell-text-hit-test";
import type {
  DataCellKind,
  DataCellValue,
  DataCellValueMeta,
} from "@/registry/new-york-v4/ui/data-cell-types";
import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";
import { useKeyedLayoutEffect } from "@/hooks/use-keyed-layout-effect";
import { joinEffectKey } from "@/lib/effect-key";

function focusDataCellTextInput(
  input: HTMLInputElement | null,
  activationSource: DataCellActivationSource | undefined,
) {
  if (!input) return null;
  input.focus({ preventScroll: true });

  if (input.type !== "text" && input.type !== "search") return;

  const selectionIndex =
    activationSource?.kind === "pointer"
      ? (activationSource.selectionOffset ??
        getDataCellTextSelectionOffset({
          clientX: activationSource.clientX,
          input,
          value: input.value,
        }))
      : input.value.length;
  input.setSelectionRange(selectionIndex, selectionIndex);
}

function initialInputValueForActivation({
  activationSource,
  kind,
  value,
}: {
  activationSource: DataCellActivationSource | undefined;
  kind: DataCellKind;
  value: DataCellValue;
}) {
  if (
    activationSource?.kind !== "keyboard" ||
    activationSource.key.length !== 1
  ) {
    return formatDataCellEditValue(kind, value);
  }
  if (kind === "text") return activationSource.key;
  if (
    (kind === "number" || kind === "integer") &&
    /^[0-9.+-]$/.test(activationSource.key)
  ) {
    return activationSource.key;
  }
  return formatDataCellEditValue(kind, value);
}

export function DataCellInputControl({
  kind,
  value,
  disabled = false,
  name,
  placeholder,
  className,
  draft,
  autoFocus,
  activationSource,
  session,
  onFocus,
  onBlur,
  onKeyDown,
  onClick,
  onMouseUp,
  onDoubleClick,
  ...props
}: DataCellInputControlProps) {
  const initialInputValue = initialInputValueForActivation({
    activationSource,
    kind,
    value,
  });
  const [uncontrolledDraftValue, setUncontrolledDraftValue] =
    React.useState(initialInputValue);
  const inputRef = React.useRef<HTMLInputElement>(null);
  const initialInputValueRef = React.useRef(initialInputValue);
  const lastInputValueRef = React.useRef(initialInputValue);
  const inputValue = draft?.value ?? uncontrolledDraftValue;
  const openingContext = useDataCellOpeningContext(activationSource, {
    enabled: activationSource?.kind === "pointer",
    releaseAfterMicrotask: true,
  });
  const isDirty = React.useCallback(
    () => lastInputValueRef.current !== initialInputValueRef.current,
    [],
  );

  useKeyedMountEffect(
    joinEffectKey([activationSource, draft?.value, kind, value]),
    () => {
      if (draft?.value !== undefined) return;
      setUncontrolledDraftValue(
        initialInputValueForActivation({
          activationSource,
          kind,
          value,
        }),
      );
    },
  );

  useKeyedMountEffect(joinEffectKey([inputValue]), () => {
    lastInputValueRef.current = inputValue;
  });

  useKeyedLayoutEffect(joinEffectKey([activationSource, autoFocus]), () => {
    if (!autoFocus && !activationSource) return;
    focusDataCellTextInput(inputRef.current, activationSource);
  });

  const commitCurrentInputValue = React.useCallback(
    (
      input: HTMLInputElement | null,
      {
        endEditing = true,
        markFinished = true,
        onlyIfChanged = false,
      }: {
        endEditing?: boolean;
        markFinished?: boolean;
        onlyIfChanged?: boolean;
      } = {},
    ) => {
      const rawValue = input?.value ?? lastInputValueRef.current;
      const commitValue = parseDataCellInputValue({
        kind,
        value: rawValue,
        dateTimeZone: "local",
        previousValue: value,
      });
      session.commit(
        commitValue,
        getDataCellValueMeta({
          kind,
          value: rawValue,
          isBadInput: input?.validity.badInput ?? false,
        }),
        {
          endEditing,
          markFinished,
          shouldCommit: onlyIfChanged ? isDirty : undefined,
        },
      );
    },
    [isDirty, kind, session, value],
  );
  const commitCurrentInputValueRef = React.useRef(commitCurrentInputValue);

  useKeyedMountEffect(joinEffectKey([commitCurrentInputValue]), () => {
    commitCurrentInputValueRef.current = commitCurrentInputValue;
  });

  useMountEffect(() => () => {
    commitCurrentInputValueRef.current(inputRef.current, {
      endEditing: false,
      markFinished: false,
      onlyIfChanged: true,
    });
  });

  const inputType = inputTypeForDataCell(kind);
  const {
    id,
    "aria-label": ariaLabel,
    "aria-describedby": ariaDescribedBy,
    "aria-invalid": ariaInvalid,
    ...rootProps
  } = props;

  return (
    <Input
      ref={inputRef}
      {...rootProps}
      type={inputType}
      className={cn(
        dataCellDisplayClass,
        disabled && "pointer-events-none opacity-64",
        className,
      )}
      id={id}
      name={name}
      aria-describedby={ariaDescribedBy}
      aria-invalid={ariaInvalid}
      aria-label={ariaLabel}
      data-kind={kind}
      data-mode="edit"
      value={inputValue}
      disabled={disabled}
      unstyled
      nativeInput
      inputMode={
        kind === "integer"
          ? "numeric"
          : kind === "number"
            ? "decimal"
            : undefined
      }
      step={kind === "integer" ? 1 : kind === "number" ? "any" : undefined}
      placeholder={placeholder}
      onChange={(event) => {
        const nextValue = event.currentTarget.value;
        lastInputValueRef.current = nextValue;
        if (draft?.value === undefined) setUncontrolledDraftValue(nextValue);
        draft?.onChange?.(
          nextValue,
          getDataCellValueMeta({
            kind,
            value: nextValue,
            isBadInput: event.currentTarget.validity.badInput,
          }),
        );
      }}
      onFocus={onFocus}
      onBlur={(event) => {
        const rawValue = event.currentTarget.value;
        if (
          openingContext.shouldCancelDismiss({ kind: "focus-out" }) &&
          rawValue === initialInputValueRef.current
        ) {
          onBlur?.(event);
          return;
        }
        commitCurrentInputValue(event.currentTarget);
        onBlur?.(event);
      }}
      onKeyDown={(event) => {
        onKeyDown?.(event);
        if (event.defaultPrevented) return;
        if (event.key === "Enter") {
          commitCurrentInputValue(event.currentTarget);
          event.currentTarget.blur();
          event.preventDefault();
          return;
        }
        if (event.key === "Escape") {
          session.cancel();
          event.currentTarget.blur();
          event.preventDefault();
          return;
        }
      }}
      onMouseUp={(event) => {
        onMouseUp?.(event);
      }}
      onClick={(event) => {
        onClick?.(event);
      }}
      onDoubleClick={onDoubleClick}
    />
  );
}

function inputTypeForDataCell(
  kind: DataCellKind,
): React.HTMLInputTypeAttribute {
  if (kind === "number" || kind === "integer") return "number";
  return "text";
}

import {
  createDataCellPointerActivationSource,
  type DataCellActivationSource,
} from "@/registry/new-york-v4/ui/data-cell-activation";
import { getDataCellDisplayTextSelectionOffset } from "@/registry/new-york-v4/ui/data-cell-text-hit-test";

export function getDataCellTextPointerActivationSource({
  clientX,
  clientY,
  detail,
  displayElement,
  event,
  value,
}: {
  clientX: number;
  clientY: number;
  detail: number;
  displayElement: HTMLElement | null;
  event?: Event;
  value: string | null | undefined;
}): Extract<DataCellActivationSource, { kind: "pointer" }> {
  const activationSource = createDataCellPointerActivationSource({
    clientX,
    clientY,
    detail,
    event,
  });
  const textElement = displayElement?.querySelector<HTMLElement>(
    '[data-slot="data-cell-value"]',
  );
  if (!textElement) return activationSource;
  activationSource.selectionOffset = getDataCellDisplayTextSelectionOffset({
    clientX,
    clientY,
    textElement,
    value: value === null || value === undefined ? "" : String(value),
  });
  return activationSource;
}

import { measureNaturalWidth, prepareWithSegments } from "@chenglou/pretext";

type MeasurePrefixWidth = (value: string) => number;
type CachedTextMeasurement = {
  widthsByOffset: Map<number, number>;
};

const TEXT_MEASUREMENT_CACHE_LIMIT = 500;
const textMeasurementCache = new Map<string, CachedTextMeasurement>();

export function getMeasuredTextSelectionOffset({
  measurePrefixWidth,
  targetX,
  value,
}: {
  measurePrefixWidth: MeasurePrefixWidth;
  targetX: number;
  value: string;
}): number {
  if (value.length === 0) return 0;

  const boundaries = graphemeBoundaries(value);
  const lastIndex = boundaries.length - 1;
  const measuredWidths = new Map<number, number>();
  const widthAtBoundary = (index: number) => {
    const offset = boundaries[index] ?? value.length;
    const cached = measuredWidths.get(offset);
    if (cached !== undefined) return cached;
    const width = safeMeasuredWidth(() =>
      measurePrefixWidth(value.slice(0, offset)),
    );
    measuredWidths.set(offset, width);
    return width;
  };
  const fullWidth = widthAtBoundary(lastIndex);
  if (targetX <= 0 || fullWidth <= 0) return 0;
  if (targetX >= fullWidth) return value.length;

  let low = 0;
  let high = lastIndex;
  while (low < high) {
    const mid = Math.floor((low + high) / 2);
    const width = widthAtBoundary(mid);
    if (width < targetX) low = mid + 1;
    else high = mid;
  }

  const nextIndex = low;
  const previousIndex = Math.max(0, nextIndex - 1);
  const previousWidth = widthAtBoundary(previousIndex);
  const nextWidth = widthAtBoundary(nextIndex);

  return targetX - previousWidth <= nextWidth - targetX
    ? (boundaries[previousIndex] ?? 0)
    : (boundaries[nextIndex] ?? value.length);
}

export function getDataCellTextSelectionOffset({
  clientX,
  input,
  value,
}: {
  clientX: number;
  input: HTMLInputElement;
  value: string;
}): number {
  const valueLength = value.length;
  if (valueLength === 0) return 0;

  const rect = input.getBoundingClientRect();
  if (rect.width <= 0) return valueLength;

  const styles = globalThis.getComputedStyle(input);
  const paddingLeft = numericCssPixels(styles.paddingLeft);
  const paddingRight = numericCssPixels(styles.paddingRight);
  const contentLeft = rect.left + paddingLeft;
  const contentWidth = Math.max(1, rect.width - paddingLeft - paddingRight);
  const targetX = clientX - contentLeft + input.scrollLeft;

  if (!canUsePretextHitTest(styles)) {
    return getLinearTextSelectionOffset({
      contentWidth,
      targetX,
      valueLength,
    });
  }

  const font = styles.font;
  const letterSpacing = numericCssPixels(styles.letterSpacing);

  try {
    return getPretextTextSelectionOffset({
      font,
      letterSpacing,
      targetX,
      value,
    });
  } catch {
    return getLinearTextSelectionOffset({
      contentWidth,
      targetX,
      valueLength,
    });
  }
}

export function getDataCellDisplayTextSelectionOffset({
  clientX,
  clientY: _clientY,
  textElement,
  value,
}: {
  clientX: number;
  clientY: number;
  textElement: HTMLElement;
  value: string;
}): number {
  return getDataCellTextSelectionOffsetFromElement({
    clientX,
    element: textElement,
    value,
  });
}

function getDataCellTextSelectionOffsetFromElement({
  clientX,
  element,
  value,
}: {
  clientX: number;
  element: HTMLElement;
  value: string;
}): number {
  const valueLength = value.length;
  if (valueLength === 0) return 0;

  const rect = element.getBoundingClientRect();
  if (rect.width <= 0) return valueLength;

  const styles = globalThis.getComputedStyle(element);
  const paddingLeft = numericCssPixels(styles.paddingLeft);
  const paddingRight = numericCssPixels(styles.paddingRight);
  const contentLeft = rect.left + paddingLeft;
  const contentWidth = Math.max(1, rect.width - paddingLeft - paddingRight);
  const targetX = clientX - contentLeft;

  if (!canUsePretextHitTest(styles)) {
    return getLinearTextSelectionOffset({
      contentWidth,
      targetX,
      valueLength,
    });
  }

  const font = styles.font;
  const letterSpacing = numericCssPixels(styles.letterSpacing);

  try {
    return getPretextTextSelectionOffset({
      font,
      letterSpacing,
      targetX,
      value,
    });
  } catch {
    return getLinearTextSelectionOffset({
      contentWidth,
      targetX,
      valueLength,
    });
  }
}

function getPretextTextSelectionOffset({
  font,
  letterSpacing,
  targetX,
  value,
}: {
  font: string;
  letterSpacing: number;
  targetX: number;
  value: string;
}): number {
  const measurement = cachedTextMeasurement({
    font,
    letterSpacing,
    value,
  });

  return getMeasuredTextSelectionOffset({
    value,
    targetX,
    measurePrefixWidth: (prefix) => {
      const offset = prefix.length;
      const cached = measurement.widthsByOffset.get(offset);
      if (cached !== undefined) return cached;
      const width = measureNaturalWidth(
        prepareWithSegments(prefix, font, {
          letterSpacing,
          whiteSpace: "pre-wrap",
        }),
      );
      measurement.widthsByOffset.set(offset, width);
      return width;
    },
  });
}

function cachedTextMeasurement({
  font,
  letterSpacing,
  value,
}: {
  font: string;
  letterSpacing: number;
  value: string;
}): CachedTextMeasurement {
  const key = `${font}\n${letterSpacing}\n${value}`;
  const cached = textMeasurementCache.get(key);
  if (cached) {
    textMeasurementCache.delete(key);
    textMeasurementCache.set(key, cached);
    return cached;
  }

  const measurement: CachedTextMeasurement = {
    widthsByOffset: new Map(),
  };
  textMeasurementCache.set(key, measurement);
  if (textMeasurementCache.size > TEXT_MEASUREMENT_CACHE_LIMIT) {
    const oldestKey = textMeasurementCache.keys().next().value;
    if (oldestKey !== undefined) textMeasurementCache.delete(oldestKey);
  }
  return measurement;
}

function getLinearTextSelectionOffset({
  contentWidth,
  targetX,
  valueLength,
}: {
  contentWidth: number;
  targetX: number;
  valueLength: number;
}): number {
  const ratio = Math.min(1, Math.max(0, targetX / contentWidth));
  return Math.min(valueLength, Math.max(0, Math.round(ratio * valueLength)));
}

function canUsePretextHitTest(styles: CSSStyleDeclaration): boolean {
  const direction = styles.direction || "ltr";
  const textAlign = styles.textAlign || "start";
  return (
    !isJsdomEnvironment() &&
    direction === "ltr" &&
    (textAlign === "left" || textAlign === "start" || textAlign === "") &&
    styles.font !== ""
  );
}

function isJsdomEnvironment(): boolean {
  return (
    globalThis.navigator?.userAgent.toLowerCase().includes("jsdom") ?? false
  );
}

function graphemeBoundaries(value: string): number[] {
  if (typeof Intl !== "undefined" && "Segmenter" in Intl) {
    const boundaries = [0];
    const segmenter = new Intl.Segmenter(undefined, {
      granularity: "grapheme",
    });
    for (const segment of segmenter.segment(value)) {
      boundaries.push(segment.index + segment.segment.length);
    }
    return boundaries;
  }

  const boundaries = [0];
  let offset = 0;
  for (const codePoint of Array.from(value)) {
    offset += codePoint.length;
    boundaries.push(offset);
  }
  return boundaries;
}

function numericCssPixels(value: string): number {
  const parsed = Number.parseFloat(value);
  return Number.isFinite(parsed) ? parsed : 0;
}

function safeMeasuredWidth(measure: () => number): number {
  const width = measure();
  return Number.isFinite(width) ? Math.max(0, width) : 0;
}

import type * as React from "react";

export type DataCellKindModel = {
  text: {
    value: string | null;
    commitValue: string | null;
  };
  number: {
    value: number | string | null;
    commitValue: number | null;
  };
  integer: {
    value: number | string | null;
    commitValue: number | null;
  };
  boolean: {
    value: boolean | null;
    commitValue: boolean;
  };
  select: {
    value: string | null;
    commitValue: string | null;
  };
  date: {
    value: string | null;
    commitValue: string | null;
  };
  time: {
    value: string | null;
    commitValue: string | null;
  };
  "date-time": {
    value: string | null;
    commitValue: string | null;
  };
};

export type DataCellKind = keyof DataCellKindModel;

export type DataCellValueForKind<Kind extends DataCellKind> =
  DataCellKindModel[Kind]["value"];
export type DataCellCommitValueForKind<Kind extends DataCellKind> =
  DataCellKindModel[Kind]["commitValue"];
export type DataCellValue = DataCellValueForKind<DataCellKind> | undefined;
export type DataCellCommitValue = DataCellCommitValueForKind<DataCellKind>;
export type DataCellDateTimeZone = "local" | "preserve" | "utc";

export type DataCellValueMeta = {
  kind: DataCellKind;
  rawValue: string;
  isEmpty: boolean;
  isValid: boolean;
};

export type DataCellSelectOption = {
  value: string;
  label: React.ReactNode;
  disabled?: boolean;
  className?: string;
};

export type DataCellCommitHandler = (
  value: DataCellCommitValue,
  meta: DataCellValueMeta,
) => void;

type DataCellNativeProps = Omit<
  React.HTMLAttributes<HTMLElement>,
  "children" | "defaultValue" | "onChange"
>;

type DataCellBaseProps<Kind extends DataCellKind> = DataCellNativeProps & {
  kind: Kind;
  value?: DataCellValueForKind<Kind>;
  editable?: boolean;
  active?: boolean;
  disabled?: boolean;
  name?: string;
  autoFocus?: boolean;
  onEditingEnd?: () => void;
  onActiveChange?: (active: boolean) => void;
};

type DataCellPlaceholderProps = {
  placeholder?: string;
};

type DataCellDraftProps = {
  draftValue?: string;
  onDraftValueChange?: (value: string, meta: DataCellValueMeta) => void;
};

type DataCellOpenProps = {
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
};

type DataCellFormatProps<Kind extends DataCellKind> = {
  formatValue?: (
    value: DataCellValueForKind<Kind> | undefined,
    meta: { kind: Kind },
  ) => React.ReactNode;
};

type DataCellCommitProps<Kind extends DataCellKind> = {
  onCommit?: (
    value: DataCellCommitValueForKind<Kind>,
    meta: DataCellValueMeta,
  ) => void;
};

type DataCellTextProps = DataCellBaseProps<"text"> &
  DataCellPlaceholderProps &
  DataCellDraftProps &
  DataCellFormatProps<"text"> &
  DataCellCommitProps<"text">;

type DataCellNumberProps = DataCellBaseProps<"number"> &
  DataCellPlaceholderProps &
  DataCellDraftProps &
  DataCellFormatProps<"number"> &
  DataCellCommitProps<"number">;

type DataCellIntegerProps = DataCellBaseProps<"integer"> &
  DataCellPlaceholderProps &
  DataCellDraftProps &
  DataCellFormatProps<"integer"> &
  DataCellCommitProps<"integer">;

type DataCellBooleanProps = DataCellBaseProps<"boolean"> &
  DataCellCommitProps<"boolean">;

type DataCellSelectProps = DataCellBaseProps<"select"> &
  DataCellPlaceholderProps &
  DataCellOpenProps &
  DataCellFormatProps<"select"> & {
    selectOptions: DataCellSelectOption[];
  } & DataCellCommitProps<"select">;

type DataCellPickerProps<Kind extends "date" | "time" | "date-time"> =
  DataCellBaseProps<Kind> &
    DataCellPlaceholderProps &
    DataCellDraftProps &
    DataCellOpenProps &
    DataCellFormatProps<Kind> & {
      dateTimeZone?: DataCellDateTimeZone;
      showPickerIcon?: boolean;
    } & DataCellCommitProps<Kind>;

export type DataCellPropsByKind = {
  text: DataCellTextProps;
  number: DataCellNumberProps;
  integer: DataCellIntegerProps;
  boolean: DataCellBooleanProps;
  select: DataCellSelectProps;
